with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('holde sig i ro', 'phrase', 'b6b808e9-f5fc-5a8f-93f6-abcaf364bd47', 1, 'verb', null, 'to keep still', 'Du skal holde dig i ro, mens lægen undersøger dit ben.', 'You must stay still while the doctor examines your leg.'), ('holde sig i ro', 'phrase', '1ac23773-7b30-5a0a-abc7-a56cfe72c691', 2, 'verb', null, 'to take it easy', 'Efter operationen skal du holde dig i ro i et par dage.', 'After the operation, you must take it easy for a few days.'), ('afholde sig fra', 'phrase', '26ab67a8-bae4-5fd2-81f9-c7787d8626ac', 1, 'verb', null, 'to refrain (from something)', 'Jeg prøver at afholde mig fra slik i hverdagene.', 'I try to refrain from sweets on weekdays.'), ('få besked om', 'phrase', 'ff5bc483-ccea-5d9c-890c-1ac3b6bba8c1', 1, 'verb', null, 'to be told to (do something)', 'Jeg fik besked om at vente udenfor.', 'I was told to wait outside.'), ('byde velkommen', 'phrase', '9dda97c2-cf37-5425-a902-7036de76a42d', 1, 'verb', null, 'to welcome (a guest)', 'De byder velkommen ved døren.', 'They welcome guests at the door.'), ('smage af', 'phrase', '13430617-7976-51ff-8ccb-871653f54871', 1, 'verb', null, 'to taste of', 'Kagen smager af citron.', 'The cake tastes of lemon.'), ('sove ind', 'phrase', '6ca71b83-6b66-52e1-9cbd-fde55bddc36d', 1, 'verb', null, 'to pass away (peacefully, in one''s sleep)', 'Min gamle nabo sov ind i nat.', 'My old neighbor passed away last night.'), ('sove ud', 'phrase', 'bfc2b234-9dbf-5d2d-bfa2-6e92787b252d', 1, 'verb', null, 'to sleep in', 'Jeg sov ud i morges.', 'I slept in this morning.'), ('kaste et blik', 'phrase', 'ef6a0e29-ab34-568a-8233-63d8e6684f4c', 1, 'verb', null, 'to glance', 'Han kastede et blik på uret.', 'He glanced at the clock.'), ('kaste et blik på', 'phrase', '9e1e6008-0708-54c5-9311-fea427d222c8', 1, 'verb', null, 'to glance at', 'Han kastede et blik på uret og skyndte sig videre.', 'He glanced at the clock and hurried on.'), ('modsætte sig', 'phrase', '18105953-f518-56af-aab2-4041e9d87ed1', 1, 'verb', null, 'to oppose, to object', 'Hun modsætter sig altid nye regler på arbejdet.', 'She always opposes new rules at work.'), ('holde mund', 'phrase', '1fb0baa3-5395-550a-8ffc-c5dfad53bde9', 1, 'verb', null, 'to keep quiet', 'Han bad børnene holde mund under filmen.', 'He asked the children to keep quiet during the film.'), ('sove som en sten', 'phrase', 'fdaefabf-6a06-5831-9f13-fe07bfa8882b', 1, 'verb', null, 'to sleep like a log', 'Jeg sov som en sten hele natten.', 'I slept like a log all night.'), ('tiltrække sig', 'phrase', '284d241e-6c61-5809-8cdd-cfbe85169a04', 1, 'verb', null, 'to attract (attention)', 'Hendes nye kjole tiltrækker sig meget opmærksomhed.', 'Her new dress attracts a lot of attention.'), ('en stor tjeneste', 'phrase', 'cf44a265-de4d-5948-8a5f-b711100a7d9f', 1, 'phrase', null, 'a big favour', 'Kan du gøre mig en stor tjeneste og hente børnene i dag?', 'Can you do me a big favor and pick up the kids today?'), ('gøre tjeneste', 'phrase', 'd049ecb8-06ae-5a5a-a99d-31c501b9840c', 1, 'verb', null, 'to serve (in the military)', 'Min bror gør tjeneste i hæren lige nu.', 'My brother is serving in the army right now.'), ('gøre tjeneste', 'phrase', '91ed7bc0-d08b-5939-b875-c55353ea4d72', 2, 'verb', null, 'to serve (a purpose)', 'Den gamle sofa gør tjeneste som seng.', 'The old sofa serves as a bed.'), ('gøre grin med', 'phrase', '9e6566e3-a905-5890-8402-0a7f58dfecc8', 1, 'verb', null, 'to make fun of', 'De andre børn gjorde grin med hans nye frisure.', 'The other children made fun of his new hairstyle.'), ('sænke sig', 'phrase', 'a6434e30-cabd-5246-b428-0b88d3c24d84', 1, 'verb', null, 'to descend, to lower oneself', 'Tågen sænkede sig langsomt over marken.', 'The fog slowly descended over the field.'), ('stride med', 'phrase', 'f64d66df-a234-5906-9c22-6698d1fd3591', 1, 'verb', null, 'to struggle with (difficulties)', 'Hun strider med lektierne hver aften.', 'She struggles with her homework every evening.'), ('kredse om', 'phrase', '8104dc6f-5f0b-5686-a26c-9c92644a7d92', 1, 'verb', null, 'to revolve around (a topic)', 'Samtalen kredsede om vejret hele aftenen.', 'The conversation revolved around the weather all evening.'), ('kredse rundt', 'phrase', 'bef07b60-b152-523d-b87d-7991ec01ad2d', 1, 'verb', null, 'to circle around (something)', 'Månen kredser rundt om jorden hele tiden.', 'The moon revolves around the earth all the time.'), ('være fan af', 'phrase', 'c09bd221-e64d-5b77-9cb5-82ca3a7d86d9', 1, 'verb', null, 'to be a fan of', 'Jeg er fan af den nye film.', 'I''m a fan of the new movie.'), ('skrue op', 'phrase', '3b69ba29-e8aa-5012-8008-ebfcb1c8784b', 1, 'verb', null, 'to turn up (volume, intensity)', 'Han skruer op for musikken om aftenen.', 'He turns up the music in the evening.'), ('skrue op for', 'phrase', '776df6fb-dc48-5f03-a120-98902dab4553', 1, 'verb', null, 'to turn up (volume, power)', 'Hun skruer op for musikken i stuen.', 'She turns up the music in the living room.'), ('betale forud', 'phrase', '11758c72-0de7-5cb7-9195-1a350beaf673', 1, 'verb', null, 'to pay in advance', 'Du skal betale forud for opholdet.', 'You must pay in advance for the stay.'), ('bøde på', 'phrase', 'e9322329-7220-5aae-beb4-c5a941d10c7f', 1, 'verb', null, 'to make up for (a shortcoming)', 'Han bøder på sin manglende erfaring med hårdt arbejde.', 'He makes up for his lack of experience with hard work.'), ('grine sig halvt ihjel', 'phrase', '5968563b-a914-5e99-8cd1-93c91aaae801', 1, 'verb', null, 'to laugh one''s head off', 'Vi grinede os halvt ihjel over den sjove film.', 'We laughed our heads off at the funny film.'), ('råde over', 'phrase', 'dac37b8c-2edf-59ea-a197-e872dbd11b9e', 1, 'verb', null, 'to have at one''s disposal', 'Vi råder over tre mødelokaler på kontoret.', 'We have three meeting rooms at our disposal in the office.'), ('spille falsk', 'phrase', '2f0b3359-da1a-5746-b34b-7898641344d2', 1, 'verb', null, 'to cheat (in a game)', 'Han spiller falsk når vi spiller kort.', 'He cheats when we play cards.'), ('synge falsk', 'phrase', '71615f91-63d2-54e3-b44a-7204af589be7', 1, 'verb', null, 'to sing off-key', 'Hun synger falsk hver gang hun prøver.', 'She sings out of tune every time she tries.'), ('tage i betragtning', 'phrase', 'e7d6bd5a-e57a-5ae3-baa6-28fe5eabbdf4', 1, 'verb', null, 'to take into account', 'Vi skal tage i betragtning, at priserne er steget.', 'We must take into account that prices have increased.'), ('standse ved', 'phrase', '0f5e8446-3e5b-5084-9130-de8c45d99e87', 1, 'verb', null, 'to stop at', 'Bussen standser ved stationen hver morgen.', 'The bus stops at the station every morning.'), ('beklage sig', 'phrase', 'e678a06b-255c-5611-b66b-33d2f8355cea', 1, 'verb', null, 'to complain', 'Hun beklager sig altid over vejret.', 'She always complains about the weather.'), ('tilpasse sig', 'phrase', '760382ec-fd3e-559d-a625-575d7396acf5', 1, 'verb', null, 'to adapt', 'Dyret tilpasser sig langsomt det nye miljø.', 'The animal slowly adapts to the new environment.'), ('have en affære', 'phrase', '0f50d1f4-024b-56c0-a2c7-987905d89c5d', 1, 'verb', null, 'to have an affair', 'Hun har en affære med sin kollega.', 'She is having an affair with her colleague.'), ('være arbejdsløs', 'phrase', 'dbbd758c-5a14-546d-bc4b-e06d219f9b30', 1, 'verb', null, 'to be unemployed', 'Han er arbejdsløs lige nu.', 'He is unemployed right now.'), ('forsikre sig om', 'phrase', 'bba8ac43-2a71-5169-89e7-a4ac80e98571', 1, 'verb', null, 'to make sure (by checking)', 'Jeg forsikrer mig om, at døren er låst, inden jeg går i seng.', 'I make sure the door is locked before I go to bed.'), ('skride frem', 'phrase', 'b57bcba3-7ae6-5bb1-8a88-5f94a2238407', 1, 'verb', null, 'to progress', 'Byggeriet skrider frem efter planen.', 'Construction is progressing according to plan.'), ('dyrke motion', 'phrase', '1aeda231-43a3-53d3-ae14-b7c88c9dcd6f', 1, 'verb', null, 'to exercise (do physical activity)', 'Jeg dyrker motion hver morgen før arbejde.', 'I exercise every morning before work.'), ('hygge sig', 'phrase', '66a6f588-48df-51ae-883d-4d5a9b150af8', 1, 'verb', null, 'to have a cosy, pleasant time together', 'Vi hygger os altid med et glas vin om aftenen.', 'We always have a cosy time together with a glass of wine in the evening.'), ('synke ned', 'phrase', 'fed971a6-07c6-5ffd-a6c5-7430045e85ca', 1, 'verb', null, 'to sink down (into liquid or a soft substance)', 'Stenen synker ned i vandet.', 'The stone sinks into the water.'), ('rende væk', 'phrase', '55fc6ab9-3ee9-5ed0-81c9-9c34950e87ae', 1, 'verb', null, 'to run away', 'Hunden rendte væk, da den så katten.', 'The dog ran away when it saw the cat.'), ('smutte forbi', 'phrase', 'fb37c36c-8ec6-58a1-b4da-f6a1f2da8cec', 1, 'verb', null, 'to pop by', 'Jeg smutter forbi bageren på vej hjem.', 'I drop by the bakery on my way home.'), ('klæde sig ud som', 'phrase', '35f289fb-eefe-5f49-b079-841e09a57f28', 1, 'verb', null, 'to dress up as', 'Hun klædte sig ud som en pirat til fastelavn.', 'She dressed up as a pirate for Carnival.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'pipeline-phrases-0010' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
